UPDATE document
SET status = 'DRAFT', updated_at = NOW()
WHERE doc_id = #{docId}
AND employee_id = #{employeeId}
AND status = 'PENDING'
AND NOT EXISTS (SELECT 1 FROM approval_line al
WHERE al.doc_id = #{docId}
AND al.approval_status != 'PENDING')

mapper.sql:
WHERE employee_id = #{employeeId}
AND status != 'DRAFT'

	AND title LIKE CONCAT('%', #{p.keyword}, '%')


	AND document_type = #{p.docType}


	AND status = #{p.status}

mapper.select:
SELECT d.doc_id, d.title, d.document_type, d.status, d.is_urgent,d.due_date, d.approval_type, d.employee_id, d.created_at, d.updated_at, de.name AS drafter_name, de.position AS drafter_position, dt.team_name AS drafter_team, al.approval_line_id, al.approver_id, al.approval_order, al.round, al.approval_status, e.name, e.position, t.team_name FROM document d
JOIN (SELECT doc_id FROM document
ORDER BY doc_id DESC
LIMIT #{p.size} OFFSET #{p.offset}
) p ON p.doc_id = d.doc_id JOIN employee de ON d.employee_id = de.employee_id LEFT JOIN team dt ON de.team_id = dt.team_id JOIN approval_line al ON d.doc_id = al.doc_id AND JOIN employee e ON al.approver_id = e.employee_id LEFT JOIN team t ON e.team_id = t.team_id ORDER BY d.doc_id DESC, al.approval_order

SELECT d.doc_id, d.title, d.document_type, d.status, d.is_urgent,d.due_date, d.approval_type, d.employee_id, d.created_at, d.updated_at, de.name AS drafter_name, de.position AS drafter_position, dt.team_name AS drafter_team, al.approval_line_id, al.approver_id, al.approval_order, al.round, al.approval_status, e.name, e.position, t.team_name FROM document d
JOIN (SELECT doc_id FROM (
) pick ORDER BY doc_id DESC
LIMIT #{p.size} OFFSET #{p.offset}
) p ON p.doc_id = d.doc_id JOIN employee de ON d.employee_id = de.employee_id LEFT JOIN team dt ON de.team_id = dt.team_id JOIN approval_line al ON d.doc_id = al.doc_id AND JOIN employee e ON al.approver_id = e.employee_id LEFT JOIN team t ON e.team_id = t.team_id ORDER BY d.doc_id DESC, al.approval_order

mapper.sql:
SELECT DISTINCT al2.doc_id FROM approval_line al2 JOIN document cd ON cd.doc_id = al2.doc_id JOIN employee ce ON cd.employee_id = ce.employee_id WHERE al2.approver_id = #{employeeId} AND al2.approval_status != 'PENDING'
AND (cd.title LIKE CONCAT('%', #{p.keyword}, '%') OR ce.name LIKE CONCAT('%', #{p.keyword}, '%'))
AND cd.document_type = #{p.docType}
AND cd.status = #{p.status}

mapper.select:
SELECT d.doc_id, d.title, d.document_type, d.status, d.is_urgent,d.due_date, d.approval_type, d.employee_id, d.created_at, d.updated_at, de.name AS drafter_name, de.position AS drafter_position, dt.team_name AS drafter_team, al.approval_line_id, al.approver_id, al.approval_order, al.round, al.approval_status, e.name, e.position, t.team_name FROM document d JOIN (SELECT doc_id FROM (
) pick ORDER BY doc_id DESC
LIMIT #{p.size} OFFSET #{p.offset}
) p ON p.doc_id = d.doc_id JOIN employee de ON d.employee_id = de.employee_id LEFT JOIN team dt ON de.team_id = dt.team_id JOIN approval_line al ON d.doc_id = al.doc_id AND JOIN employee e ON al.approver_id = e.employee_id LEFT JOIN team t ON e.team_id = t.team_id ORDER BY d.doc_id DESC, al.approval_order

